targets.expr:
max by(node) (max_over_time((100 * sum by(node) (
  container_memory_working_set_bytes{container!="", image!=""}
  * on(namespace,pod) group_left(node) max by(namespace,pod,node) (kube_pod_info{node=~"$node"})
) / max by(node) (kube_node_status_allocatable{node=~"$node", resource="memory"}))[$__range:1m]))

100 * sum by(node) (
  container_memory_working_set_bytes{container!="", image!=""}
  * on(namespace,pod) group_left(node) max by(namespace,pod,node) (kube_pod_info{node=~"$node"})
) / max by(node) (kube_node_status_allocatable{node=~"$node", resource="memory"})

min by(nodename,mountpoint) (
  100 * node_filesystem_avail_bytes{fstype!~"tmpfs|overlay|squashfs", mountpoint=~"/|/var|/var/lib/docker|/var/lib/kubelet|/var/lib/containerd"} / node_filesystem_size_bytes{fstype!~"tmpfs|overlay|squashfs", mountpoint=~"/|/var|/var/lib/docker|/var/lib/kubelet|/var/lib/containerd"}
  * on(instance) group_left(nodename) max by(instance,nodename) (node_uname_info{nodename=~"$node"})
)
